#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int countArrays(vector<int>& original, vector<vector<int>>& bounds) {
        int n = original.size();
        long long lo = bounds[0][0];
        long long hi = bounds[0][1];
        for (int i = 1; i < n; i++) {
            long long diff = (long long)original[i] - original[0];
            lo = max(lo, (long long)bounds[i][0] - diff);
            hi = min(hi, (long long)bounds[i][1] - diff);
        }
        return max(0LL, hi - lo + 1);
    }
};

class Solution {
    public int countArrays(int[] original, int[][] bounds) {
        int n = original.length;
        long lo = bounds[0][0];
        long hi = bounds[0][1];
        for (int i = 1; i < n; i++) {
            long diff = (long) original[i] - original[0];
            lo = Math.max(lo, bounds[i][0] - diff);
            hi = Math.min(hi, bounds[i][1] - diff);
        }
        return (int) Math.max(0, hi - lo + 1);
    }
}

