var countArrays = function(original, bounds) {
    const n = original.length;
    let lo = bounds[0][0];
    let hi = bounds[0][1];
    for (let i = 1; i < n; i++) {
        const diff = original[i] - original[0];
        lo = Math.max(lo, bounds[i][0] - diff);
        hi = Math.min(hi, bounds[i][1] - diff);
    }
    return Math.max(0, hi - lo + 1);
};
